"""Task-local inspection: list workspace files and describe any SQLite databases."""
import os
import sqlite3

for name in sorted(os.listdir(".")):
    if os.path.isfile(name):
        print(f"FILE: {name}")
    elif os.path.isdir(name):
        print(f"DIR:  {name}/")

for name in sorted(os.listdir(".")):
    if name.endswith(".db"):
        print(f"\n=== DATABASE: {name} ===")
        try:
            with sqlite3.connect(name) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                print("TABLES:", [t["name"] for t in tables])
                for t in tables:
                    print(f"\n-- schema for {t['name']} --")
                    for row in cur.execute(
                        "SELECT sql FROM sqlite_master WHERE type='table' AND name=?",
                        (t["name"],),
                    ):
                        print(row["sql"])
                    cols = cur.execute(f'PRAGMA table_info("{t["name"]}")').fetchall()
                    print("columns:", [(c["name"], c["type"]) for c in cols])
                    count = cur.execute(
                        f'SELECT COUNT(*) AS n FROM "{t["name"]}"'
                    ).fetchone()
                    print("row count:", count["n"])
        except Exception as exc:  # noqa: BLE001 - inspection should not abort
            print(f"ERROR reading {name}: {exc}")

